SELECT A.seq, A.nm, A.expire_dt, B.img_url, C.nm as category_nm FROM tblmicou_coupon as A LEFT JOIN tblmicou_img_file as B ON A.img_file_seq = B.seq LEFT JOIN tblmicou_category as C ON A.category_seq = C.seq
A.del_yn = 'N' AND A.usr_grp_cd = #{usr_grp_cd}
AND A.category_seq = #{category_seq}
AND A.nm LIKE CONCAT('%',#{nm},'%')
AND A.expire_dt >= #{expire_dt}
ORDER BY A.expire_dt DESC
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

SELECT count(*) FROM tblmicou_coupon as A LEFT JOIN tblmicou_img_file as B ON A.img_file_seq = B.seq LEFT JOIN tblmicou_category as C ON A.category_seq = C.seq
A.del_yn = 'N' AND A.usr_grp_cd = #{usr_grp_cd}
AND A.category_seq = #{category_seq}
AND A.nm LIKE CONCAT('%',#{nm},'%')
AND A.expire_dt >= #{expire_dt}

SELECT A.seq, A.nm, A.expire_dt, B.img_url, C.nm as category_nm FROM tblmicou_coupon as A LEFT JOIN tblmicou_img_file as B ON A.img_file_seq = B.seq LEFT JOIN tblmicou_category as C ON A.category_seq = C.seq
A.del_yn = 'N' AND A.usr_grp_cd = #{usr_grp_cd} AND A.expire_dt >= NOW()
AND A.category_seq = #{category_seq}
AND A.nm LIKE CONCAT('%',#{nm},'%')
AND A.expire_dt <= #{expire_dt}
ORDER BY A.reg_dt DESC
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

SELECT count(*) FROM tblmicou_coupon as A LEFT JOIN tblmicou_img_file as B ON A.img_file_seq = B.seq LEFT JOIN tblmicou_category as C ON A.category_seq = C.seq
A.del_yn = 'N' AND A.usr_grp_cd = #{usr_grp_cd} AND A.expire_dt >= NOW()
AND A.category_seq = #{category_seq}
AND A.nm LIKE CONCAT('%',#{nm},'%')
AND A.expire_dt <= #{expire_dt}

SELECT A.seq, A.msgkey, A.phone, C.nm as coupon_nm, A.send_dt, A.use_yn, D.img_url, CASE WHEN E.send_rst is null THEN '0' WHEN E.send_rst = '0' THEN '1' WHEN E.send_rst = '1' THEN '2' ELSE '0' END send_status FROM tblmicou_coupon_issued_log as A LEFT JOIN tblmicou_coupon_issue as B ON A.coupon_issue_seq = B.seq LEFT JOIN tblmicou_coupon as C ON B.coupon_seq = C.seq LEFT JOIN tblmicou_img_file as D ON C.img_file_seq = D.seq LEFT JOIN tblmicp_send_hst as E ON A.msgkey = E.seq
A.del_yn = 'N' AND A.usr_grp_cd = #{usr_grp_cd}
AND C.category_seq = #{category_seq}
AND A.send_dt >= #{send_start_dt}
AND A.send_dt <= #{send_end_dt}
AND A.use_yn = #{use_yn}
AND C.nm LIKE CONCAT('%',#{coupon_nm},'%')
AND E.send_rst IS NULL = '0' = '1'
ORDER BY A.reg_dt DESC
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

SELECT count(*) FROM tblmicou_coupon_issued_log as A LEFT JOIN tblmicou_coupon_issue as B ON A.coupon_issue_seq = B.seq LEFT JOIN tblmicou_coupon as C ON B.coupon_seq = C.seq LEFT JOIN tblmicou_img_file as D ON C.img_file_seq = D.seq LEFT JOIN tblmicp_send_hst as E ON A.msgkey = E.seq
A.del_yn = 'N' AND A.usr_grp_cd = #{usr_grp_cd}
AND C.category_seq = #{category_seq}
AND A.send_dt >= #{send_start_dt}
AND A.send_dt <= #{send_end_dt}
AND A.use_yn = #{use_yn}
AND C.nm LIKE CONCAT('%',#{coupon_nm},'%')
AND E.send_rst IS NULL = '0' = '1'

SELECT list_val
FROM tblmi_set_lst
WHERE del_dt = 'N'
  	and def_yn = 'Y'

	and list_tp_id = #{list_tp_id}


	and list_dt_id = #{list_dt_id}


	and usr_grp_cd = #{usr_grp_cd}


	and use_yn = #{use_yn}

SELECT cd_val
FROM tblmi_comm_cd
WHERE
    grp_id = #{grp_id}
AND cd_id = #{cd_id}

