UPDATE tblmicou_img_file
SET del_yn = 'Y'
WHERE seq = #{imageSeq}

UPDATE tblmicou_coupon as A SET A.category_seq = #{category_seq}, A.nm = #{nm}, A.title = #{title}, A.descr = #{descr}, A.notice = #{notice}, A.expire_dt = #{expire_dt}, A.daily_start_time = #{daily_start_time}, A.daily_end_time = #{daily_end_time}, A.available_day = #{available_day},
A.img_file_seq = #{img_file_seq},
A.content = #{content}, A.upd_id = #{upd_id} WHERE A.seq = #{seq}

UPDATE tblmicou_coupon_issue
SET
	target_cnt = #{target_cnt}
WHERE
    seq = #{seq}

UPDATE tblmicou_coupon_issued_log
SET
	del_yn = 'Y',
	upd_id = #{upd_id}
WHERE seq in

	#{seq}
